import { tags } from "typia";

/**
 * Simple aggregation pair used for dashboards and summaries. Represents a label
 * and its numeric count. Use this for action breakdowns, top-N lists, and
 * similar aggregated outputs.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IKeyValue = {
  /**
   * Aggregation key or label. In moderation breakdown contexts this is
   * typically the moderation action type (e.g.,
   * 'hide','remove','warn','suspend','ban').
   */
  key: string;

  /**
   * Integer value associated with the key (for example, a count). Must be a
   * non-negative integer (>= 0).
   */
  value: number & tags.Type<"int32"> & tags.Minimum<0>;
};
